{
  "workflow": {
    "activities": [
      {
        "id": "A1",
        "name": "Receive Measurement Request",
        "actor": "Measurement Engineer",
        "system": "None (manual intake)",
        "inputs": ["Measurement request (wafer type, measurement specification)"],
        "outputs": ["Acknowledged measurement request"]
      },
      {
        "id": "A2",
        "name": "Select Equipment Type",
        "actor": "Measurement Engineer",
        "system": "None (engineer judgment)",
        "inputs": ["Measurement type", "Wafer condition", "Engineer knowledge of equipment capabilities"],
        "outputs": ["Selected equipment type"]
      },
      {
        "id": "A3",
        "name": "Check Equipment Availability and Qualification Status",
        "actor": "Measurement Engineer",
        "system": "Equipment Reservation System",
        "inputs": ["Selected equipment type"],
        "outputs": ["Equipment availability status", "Equipment qualification status"]
      },
      {
        "id": "A4",
        "name": "Reserve Equipment",
        "actor": "Measurement Engineer",
        "system": "Equipment Reservation System",
        "inputs": ["Confirmed available and qualified equipment"],
        "outputs": ["Equipment reservation record", "Equipment usage log entry"]
      },
      {
        "id": "A5",
        "name": "Verify Wafer Information",
        "actor": "Measurement Engineer",
        "system": "None (manual check)",
        "inputs": ["Physical wafer", "Measurement request details"],
        "outputs": ["Confirmed wafer identity match"]
      },
      {
        "id": "A6",
        "name": "Perform Tool-Specific Wafer Preparation",
        "actor": "Measurement Engineer",
        "system": "None (manual physical handling)",
        "inputs": ["Reserved equipment", "Wafer", "Tool-specific preparation procedure"],
        "outputs": ["Prepared wafer ready for measurement"]
      },
      {
        "id": "A7",
        "name": "Verify Recipe Approval Status",
        "actor": "Measurement Engineer",
        "system": "Recipe Management System (implied)",
        "inputs": ["Measurement recipe identifier"],
        "outputs": ["Recipe approval status"]
      },
      {
        "id": "A8",
        "name": "Load and Execute Measurement Recipe",
        "actor": "Measurement Engineer",
        "system": "Equipment Control Software",
        "inputs": ["Approved measurement recipe", "Prepared wafer", "Reserved equipment"],
        "outputs": ["Raw measurement output data"]
      },
      {
        "id": "A9",
        "name": "Validate Measurement Output",
        "actor": "Measurement Engineer",
        "system": "None (manual review)",
        "inputs": ["Raw measurement output data"],
        "outputs": ["Validation decision (valid or invalid/noisy)"]
      },
      {
        "id": "A10",
        "name": "Upload Measurement Result to Repository",
        "actor": "Measurement Engineer",
        "system": "Measurement Result Repository",
        "inputs": ["Validated measurement result"],
        "outputs": ["Stored measurement result record"]
      },
      {
        "id": "A11",
        "name": "Send Request Completion Notice",
        "actor": "Measurement Engineer",
        "system": "None (manual notification or email)",
        "inputs": ["Uploaded result confirmation", "Requester contact information"],
        "outputs": ["Completion notification to requester"]
      }
    ],
    "decisions": [
      {
        "id": "D1",
        "condition": "Is the selected equipment available and qualified?",
        "branches": [
          "Yes → Proceed to A4 (Reserve Equipment)",
          "No → Return to A2 (Select alternative equipment type) or halt workflow"
        ]
      },
      {
        "id": "D2",
        "condition": "Does the wafer information match the measurement request?",
        "branches": [
          "Yes → Proceed to A6 (Wafer Preparation)",
          "No → Raise wafer information mismatch exception; halt workflow"
        ]
      },
      {
        "id": "D3",
        "condition": "Is the measurement recipe pre-approved?",
        "branches": [
          "Yes → Proceed to A8 (Load and Execute Recipe)",
          "No → Raise unapproved recipe exception; halt workflow"
        ]
      },
      {
        "id": "D4",
        "condition": "Is the measurement output valid (not noisy or erroneous)?",
        "branches": [
          "Yes → Proceed to A10 (Upload Result)",
          "No → Raise invalid output exception; halt workflow (no formal rework loop defined)"
        ]
      }
    ],
    "exceptions": [
      {
        "id": "E1",
        "name": "Equipment Unavailable or Under Maintenance",
        "trigger": "Equipment availability check at D1 fails",
        "current_handling": "Workflow cannot continue with selected tool; engineer must select alternative equipment or halt",
        "gap": "No formal fallback routing or escalation path documented"
      },
      {
        "id": "E2",
        "name": "Wafer Information Mismatch",
        "trigger": "Wafer identity does not match measurement request at D2",
        "current_handling": "Exception flagged; workflow halted",
        "gap": "No defined resolution or escalation path"
      },
      {
        "id": "E3",
        "name": "Unapproved Recipe",
        "trigger": "Recipe approval check at D3 fails",
        "current_handling": "Exception flagged; workflow halted",
        "gap": "No process defined for expediting recipe approval or selecting an alternative approved recipe"
      },
      {
        "id": "E4",
        "name": "Invalid or Noisy Measurement Output",
        "trigger": "Output validation at D4 fails",
        "current_handling": "Exception flagged; result not uploaded",
        "gap": "No rework loop, remeasurement procedure, or escalation path is formally defined"
      }
    ],
    "dependencies": [
      {"from": "A1", "to": "A2", "type": "control_flow"},
      {"from": "A2", "to": "A3", "type": "control_flow"},
      {"from": "A3", "to": "D1", "type": "control_flow"},
      {"from": "D1", "to": "A4", "type": "conditional"},
      {"from": "A4", "to": "A5", "type": "control_flow"},
      {"from": "A5", "to": "D2", "type": "control_flow"},
      {"from": "D2", "to": "A6", "type": "conditional"},
      {"from": "A6", "to": "A7", "type": "control_flow"},
      {"from": "A7", "to": "D3", "type": "control_flow"},
      {"from": "D3", "to": "A8", "type": "conditional"},
      {"from": "A8", "to": "A9", "type": "control_flow"},
      {"from": "A9", "to": "D4", "type": "control_flow"},
      {"from": "D4", "to": "A10", "type": "conditional"},
      {"from": "A10", "to": "A11", "type": "control_flow"}
    ]
  },
  "automation_opportunities": [
    {
      "target": "A3 – Check Equipment Availability and Qualification Status",
      "rationale": "The equipment reservation system is a digital system that should expose availability and qualification status programmatically. This check can be automated as a real-time query, eliminating manual lookup and reducing delay.",
      "required_data": ["Equipment reservation system API or query interface", "Equipment qualification status records"],
      "constraints": ["System must expose structured, queryable availability data", "Qualification status must be maintained and current in the system"],
      "confidence": "high"
    },
    {
      "target": "A4 – Reserve Equipment",
      "rationale": "Equipment reservation is a transactional step that, if the reservation system has a write interface, can be automated immediately following a successful availability check without engineer manual entry.",
      "required_data": ["Equipment reservation system write interface", "Selected equipment identifier", "Measurement request identifier"],
      "constraints": ["System must support automated reservation creation", "Concurrency conflicts must be handled by the system"],
      "confidence": "medium"
    },
    {
      "target": "A7 – Verify Recipe Approval Status",
      "rationale": "Recipe approval status is a binary, structured attribute that can be queried from the recipe management system automatically before recipe execution, replacing a manual check step.",
      "required_data": ["Recipe management system with approval status field", "Recipe identifier linked to measurement request"],
      "constraints": ["Recipe management system must be accessible programmatically", "Approval status must reflect real-time state"],
      "confidence": "high"
    },
    {
      "target": "A8 – Load and Execute Measurement Recipe",
      "rationale": "Recipe execution is described as a software-driven step and is noted as potentially automatable. If the equipment control software supports scripted or remote recipe invocation, this step can be triggered without manual engineer intervention.",
      "required_data": ["Equipment control software API or automation interface", "Approved recipe file or identifier", "Wafer load confirmation signal"],
      "constraints": ["Equipment control software must support remote or scripted execution", "Physical wafer loading (part of A6) must still be completed manually prior to this step"],
      "confidence": "medium"
    },
    {
      "target": "A10 – Upload Measurement Result to Repository",
      "rationale": "Once output is validated, the upload to the measurement result repository is a data transfer step that can be automated if the repository has an ingest interface and the equipment output format is structured.",
      "required_data": ["Measurement result repository upload interface", "Structured output file from equipment", "Wafer and request identifiers for metadata tagging"],
      "constraints": ["Output format must be consistent enough to map to repository schema", "Validation decision (D4) must be resolved before triggering upload"],
      "confidence": "medium"
    },
    {
      "target": "A11 – Send Request Completion Notice",
      "rationale": "Completion notification is a routine communication step that can be fully automated as a triggered message once the result upload is confirmed, using requester contact information from the original request.",
      "required_data": ["Requester contact details from measurement request record", "Upload confirmation event from measurement result repository"],
      "constraints": ["Notification system or messaging interface must be available", "Requester contact information must be captured at request intake"],
      "confidence": "high"
    },
    {
      "target": "D4 – Validate Measurement Output",
      "rationale": "Output validation could be partially automated using statistical thresholds or signal quality metrics if the equipment generates structured numerical output. Rule-based checks for noise or out-of-bounds values could replace or augment manual review.",
      "required_data": ["Defined specification limits or noise thresholds per measurement type", "Structured numeric output from equipment", "Measurement type context"],
      "constraints": ["Thresholds must be formally defined and maintained", "Edge cases may still require human review", "Validation rules must be approved before deployment"],
      "confidence": "medium"
    }
  ],
  "remaining_gaps": [
    {
      "id": "G1",
      "description": "No formal escalation or rework path is defined for any of the four exception types (equipment unavailable, wafer mismatch, unapproved recipe, invalid output). The workflow halts without a documented resolution process, creating dead ends that cannot be modeled or automated.",
      "impact": "High – exceptions cannot be handled systematically or monitored for recurrence",
      "suggested_action": "Define and document exception resolution paths, including responsible roles, time limits, and rework or retry logic for each exception type"
    },
    {
      "id": "G2",
      "description": "The tool-specific wafer preparation steps (A6) are not individually documented. Each equipment type has a distinct manual procedure, but these variants are not captured in the workflow description.",
      "impact": "High – process mining cannot distinguish tool-specific sub-paths without this detail; automation assessment for preparation steps is impossible",
      "suggested_action": "Document the preparation procedure for each equipment type as a distinct sub-process or decision branch, identifying which steps are common and which are tool-specific"
    },
    {
      "id": "G3",
      "description": "Programmatic accessibility of the measurement result repository has not been confirmed. Automation of the upload step (A10) depends on this interface existing.",
      "impact": "Medium – blocks automation of result upload and downstream notification",
      "suggested_action": "Validate with system owners whether the repository exposes an ingest API and what the accepted data format is"
    },
    {
      "id": "G4",
      "description": "Whether the equipment reservation system and measurement result repository generate queryable event logs with timestamps, wafer identifiers, tool IDs, and outcome codes has not been confirmed.",
      "impact": "High – process mining requires event log data; without confirmation of log structure and content, conformance checking and performance analysis cannot be performed",
      "suggested_action": "Audit the event logging capabilities of both systems and extract a sample log to assess completeness and queryability"
    },
    {
      "id": "G5",
      "description": "Throughput volume data (measurements per shift or per day, workload distribution across equipment types) is entirely absent. This prevents capacity analysis, bottleneck identification, and prioritization of automation investments.",
      "impact": "Medium – limits ability to assess ROI of automation and identify high-frequency pain points",
      "suggested_action": "Extract historical usage records from the equipment reservation system to estimate request volumes, cycle times, and tool utilization rates"
    },
    {
      "id": "G6",
      "description": "The engineer's equipment selection logic (A2) is undocumented and relies entirely on tacit knowledge. This creates a non-reproducible decision point that cannot be audited, trained upon, or automated.",
      "impact": "Medium – selection inconsistency may lead to suboptimal equipment use and is invisible to process analysis",
      "suggested_action": "Work with engineers to elicit and formalize the selection criteria into a documented decision table or rule set, even if informal, to enable future decision support or routing automation"
    }
  ]
}
